WITH enriched AS (SELECT id, device_code, humidity, status_bits, LAG(status_bits) OVER w_hist prev_status_bits, LEAD(temp_c) OVER w_hist next_temp_c, LAG(temp_c) OVER w_hist prev_temp_c, ROW_NUMBER() OVER w_hist seq_no, ROW_NUMBER() OVER (PARTITION BY device_code ORDER BY temp_c DESC, id) row_seq FROM device_readings WINDOW w_hist AS (PARTITION BY device_code ORDER BY humidity, id)) SELECT id, device_code, humidity, status_bits, prev_status_bits, next_temp_c, prev_temp_c, seq_no, row_seq, CASE WHEN device_code RLIKE '^(DV-02|DV-04)$' THEN 'EXTENDED' ELSE 'PRIORITY' END AS device_code_zone FROM enriched ORDER BY seq_no, status_bits DESC;
